import sys, dis, importlib.util
from pathlib import Path

import pybamm

tracked = {"children","extrapolate","fill_value","interpolating_function","interpolator","name","possible_interpolators","x","x1","x2","x3","y"}

init_fn = pybamm.expression_tree.interpolant.Interpolant.__init__
code = init_fn.__code__
instr_map = {instr.offset: instr for instr in dis.get_instructions(code)}

results = {}


def run_test(method_name):
    pairs = set()
    stack = []

    def tracer(frame, event, arg):
        if event == 'call' and frame.f_code is code:
            state = {"defs": {}, "pairs": pairs}
            for name in tracked:
                if name in frame.f_locals:
                    state["defs"][name] = code.co_firstlineno
            stack.append(state)
            frame.f_trace_opcodes = True
            return tracer

        if event == 'return' and frame.f_code is code:
            if stack:
                stack.pop()
            return tracer

        if event == 'opcode' and frame.f_code is code and stack:
            state = stack[-1]
            instr = instr_map.get(frame.f_lasti)
            if instr is None:
                return tracer
            op = instr.opname
            name = instr.argval if isinstance(instr.argval, str) else None
            if name in tracked:
                if op == 'STORE_FAST':
                    state['defs'][name] = frame.f_lineno
                elif op == 'LOAD_FAST':
                    d = state['defs'].get(name)
                    u = frame.f_lineno
                    if d is not None and u > d:
                        state['pairs'].add((name, d, u))
            return tracer

        return tracer

    sys.settrace(tracer)
    try:
        test_obj = test_cls()
        getattr(test_obj, method_name)()
    finally:
        sys.settrace(None)
    return pairs


test_path = Path('/testbed/qa_instances_eval/pybamm_qa/interpolant_init_create_copy_def_use_intersection_suite/files/tests/qa/interpolant_init_create_copy_def_use_intersection_suite_test.py')
spec = importlib.util.spec_from_file_location('qa_mod', test_path)
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)

test_cls = mod.TestInterpolantInitCreateCopyDefUseIntersectionQA
methods = [f'test_case_{i:02d}' for i in range(1, 11)]

intersection = None
for m in methods:
    p = run_test(m)
    results[m] = p
    intersection = p if intersection is None else (intersection & p)

for m in methods:
    print(m, len(results[m]))

print('INTERSECTION', len(intersection))
for item in sorted(intersection, key=lambda t:(t[0],t[1],t[2])):
    print(item)
